/* Timeline detail cards: richer notes written for JudeBible from the passage itself (no text copied from a commentary), plus "read together" links.
   Tyndale Open Study Notes excerpts (CC BY-SA 4.0) are attached automatically by timeline-detail-enrich-20261016.js. Pilot: Primeval era. Not reviewed by a scholar. */
window.JBC_TL_ENRICH = {"era.primitive.creation.1":{"flow":["창세기는 “태초에 하나님이 천지를 창조하시니라”로 시작하며, 하나님이 말씀으로 질서를 세우시는 여섯 날을 차례로 보여 줍니다. 첫 사흘에는 빛과 낮밤, 하늘(궁창)과 물, 땅과 바다와 식물처럼 ‘공간’이 구분되고, 다음 사흘에는 해·달·별, 새와 물고기, 육지 동물과 사람처럼 그 공간을 채우는 존재가 만들어집니다. 이 짝 구조 덕분에 1장은 ‘짓고 → 채우는’ 한 편의 질서 있는 이야기로 읽힙니다.","매일 “하나님이 이르시되 … 있으라 하시니 … 있었고 … 보시기에 좋았더라”는 틀이 되풀이됩니다. 마지막으로 사람은 ‘하나님의 형상’대로 남자와 여자로 지어져 땅을 돌보고 다스리라는 복을 받으며(1:26–28), 하나님이 지으신 모든 것이 “심히 좋았다”고 선언됩니다(1:31).","고대 근동에는 신들의 싸움에서 세상이 생겨났다고 전하는 이야기(예: 바벨론의 에누마 엘리시)가 있었습니다. 이와 달리 이 본문은 한 분 하나님이 말씀만으로 만물을 지으셨다고 선포하며, 해와 달조차 신이 아니라 하나님이 만드신 ‘광명체’로 부릅니다."],"read":[{"ref":"요 1:1","hash":"jhn-1:1","why":"요한은 같은 “태초”로 시작해 말씀을 통한 창조를 말합니다."},{"ref":"시 33:6","hash":"psa-33:6","why":"“여호와의 말씀으로 하늘이 지어졌으며”."},{"ref":"히 11:3","hash":"heb-11:3","why":"믿음으로 세계가 하나님의 말씀으로 지어졌음을 안다."},{"ref":"시 104:1","hash":"psa-104:1","why":"창조의 질서를 찬양하는 시."}]},"era.primitive.creation.2":{"flow":["1장이 우주 전체를 내려다보았다면 2장 4절 이하는 사람을 중심으로 이야기를 다시 풀어 갑니다. 하나님은 흙으로 사람(아담)을 빚으시고 코에 생기를 불어넣어 ‘생령’이 되게 하십니다(2:7). 히브리어로 ‘사람’(아담)과 ‘흙’(아다마)은 소리가 닮았는데, 사람이 흙에서 왔다는 사실을 말소리로도 보여 줍니다.","하나님은 동쪽 에덴에 동산을 만드시고 그 가운데 생명나무와 선악을 알게 하는 나무를 두십니다. 사람은 동산을 “경작하며 지키는” 일을 맡고(2:15), 먹지 말아야 할 한 가지가 첫 명령으로 주어집니다(2:16–17). 이어 사람이 독처하는 것이 좋지 못하다는 말씀(2:18)과 함께, 모든 짐승 가운데서도 짝을 찾지 못한 아담 앞에서 하나님이 여자를 지으시고, 아담은 “이는 내 뼈 중의 뼈요 살 중의 살”이라고 노래합니다.","2:24은 “남자가 부모를 떠나 아내와 합하여 둘이 한 몸을 이룰지로다”라고 결혼의 원형을 말합니다. 동산에서 갈라져 흐르는 네 강(비손·기혼·힛데겔·유브라데) 가운데 힛데겔과 유브라데는 알려진 강이지만 나머지는 위치가 확정되지 않아, 에덴의 정확한 위치는 학자들 사이에서 의견이 크게 갈립니다."],"read":[{"ref":"마 19:4","hash":"mat-19:4","why":"예수께서 2:24을 인용해 결혼의 뜻을 말씀하십니다."},{"ref":"고전 15:45","hash":"1co-15:45","why":"“첫 사람 아담”과 “마지막 아담”을 견줍니다."},{"ref":"엡 5:31","hash":"eph-5:31","why":"결혼의 연합을 그리스도와 교회에 견줍니다."},{"ref":"계 22:2","hash":"rev-22:2","why":"요한계시록의 생명나무."}]},"era.primitive.creation.3":{"flow":["들짐승 가운데 가장 간교한 뱀이 여자에게 “하나님이 참으로 … 하시더냐”고 물으며 하나님의 말씀을 의심하게 만듭니다(3:1). 여자는 “만지지도 말라”고 덧붙여 답하는데(3:3), 2:17에는 먹지 말라는 말씀만 있어 사람의 말이 하나님의 말씀보다 무거워진 모습이 보입니다. 뱀은 “결코 죽지 아니하리라 … 하나님과 같이 되어”라고 부추깁니다(3:4–5).","여자가 보니 그 나무가 먹음직도 하고 보암직도 하고 지혜롭게 할 만큼 탐스러워(3:6) 먹고, 곁에 있던 남편에게도 줍니다. 눈이 밝아진 두 사람은 자신들이 벗었음을 알고 무화과나무 잎으로 몸을 가립니다. 약속하신 ‘지혜’ 대신 부끄러움이 들어온 것입니다.","저녁 바람이 불 때 하나님이 동산을 거니시며 “네가 어디 있느냐”고 부르십니다(3:9). 이는 정죄에 앞선 부르심입니다. 그러나 아담은 “주께서 주셔서 나와 함께 있게 하신 여자”를, 여자는 뱀을 탓하여(3:12–13), 깨진 신뢰가 사람 사이의 관계로 번집니다."],"read":[{"ref":"롬 5:12","hash":"rom-5:12","why":"한 사람으로 죄가 세상에 들어왔다는 바울의 설명."},{"ref":"고후 11:3","hash":"2co-11:3","why":"뱀이 하와를 속인 것처럼 속임을 경계함."},{"ref":"딤전 2:13","hash":"1ti-2:13","why":"아담과 하와의 순서를 언급."},{"ref":"요일 2:16","hash":"1jn-2:16","why":"“육신의 정욕, 안목의 정욕, 이생의 자랑”을 3:6과 견주어 읽는 이들이 많습니다."}]},"era.primitive.creation.4":{"flow":["하나님은 뱀, 여자, 남자에게 차례로 말씀하십니다. 뱀에게는 저주가 선언되고, 여자의 후손과 뱀의 후손 사이에 “원수”가 있으리라는 말씀이 주어집니다(3:15). 교회 전통에서는 이 구절을 흔히 ‘원복음’이라 부르며 장차 오실 이의 승리를 가리키는 첫 약속으로 읽지만, 구절의 정확한 뜻은 해석이 나뉩니다.","여자에게는 해산의 고통과 남편과의 관계의 긴장이(3:16), 남자에게는 땅이 저주를 받아 수고해야 먹는 삶과 흙으로 돌아갈 죽음이(3:17–19) 말해집니다. 그러나 이야기는 심판으로만 끝나지 않습니다. 아담은 아내를 ‘하와’(모든 산 자의 어머니)라 부르고(3:20), 하나님은 가죽옷을 지어 입히십니다(3:21).","두 사람은 생명나무로 이어지는 길이 막혀 동산에서 쫓겨나고, 동쪽에 그룹들과 두루 도는 불 칼이 세워집니다(3:22–24). 이후 창세기는 이 ‘동쪽으로 떠남’의 방향을 가인(4:16)과 바벨(11:2) 이야기에서 되풀이합니다."],"read":[{"ref":"롬 16:20","hash":"rom-16:20","why":"평강의 하나님이 사탄을 속히 너희 발 아래에서 상하게 하신다는 약속."},{"ref":"갈 4:4","hash":"gal-4:4","why":"“여자에게서 나게 하시고”."},{"ref":"계 12:9","hash":"rev-12:9","why":"옛 뱀."},{"ref":"계 22:14","hash":"rev-22:14","why":"생명나무에 나아갈 권세."}]},"era.primitive.cain-seth.1":{"flow":["아담과 하와의 두 아들 가운데 가인은 땅을 가는 농부, 아벨은 양을 치는 목자였습니다. 두 사람이 하나님께 제물을 드렸는데, 하나님은 아벨과 그의 제물은 받으시고 가인과 그의 제물은 받지 않으셨고, 가인은 몹시 분하여 얼굴을 떨굽니다(4:3–5). 본문은 그 이유를 길게 설명하지 않으며, 히브리서 11:4는 아벨이 ‘믿음으로’ 더 나은 제사를 드렸다고 해석합니다.","하나님은 가인에게 “죄가 문에서 엎드려 너를 원하나 너는 그것을 다스릴지니라”(4:7)고 말씀하시며 돌이킬 길을 열어 주십니다. 그러나 가인은 아우를 들로 불러내어 죽이고, “내가 내 아우를 지키는 자니이까”(4:9)라고 답합니다. 땅에 스며든 아벨의 피가 하나님께 부르짖는다고 하신 뒤(4:10), 가인은 땅에서 쫓겨나 유리하는 자가 됩니다.","가인이 자기 벌이 너무 무겁다고 호소하자 하나님은 그를 죽이지 못하도록 ‘표’를 주십니다(4:15). 벌 속에서도 보호가 있음을 보여 줍니다. 가인은 에덴 동쪽 ‘놋’ 땅에 거합니다. ‘아벨’은 히브리어 ‘헤벨’로 숨결·덧없음을 뜻합니다."],"read":[{"ref":"히 11:4","hash":"heb-11:4","why":"아벨이 믿음으로 드린 제사."},{"ref":"요일 3:12","hash":"1jn-3:12","why":"가인은 악한 자에게 속하여 아우를 죽였다."},{"ref":"마 23:35","hash":"mat-23:35","why":"의인 아벨의 피."},{"ref":"히 12:24","hash":"heb-12:24","why":"아벨의 피보다 더 나은 것을 말하는 뿌린 피."}]},"era.primitive.cain-seth.2":{"flow":["가인은 아내와 동침하여 에녹을 낳고, 성을 쌓아 아들의 이름으로 부릅니다(4:17). 이후 이랏, 므후야엘, 므드사엘을 거쳐 라멕에 이르는 계보가 이어집니다(4:18). 같은 이름 ‘에녹’이 셋의 계보(5:18)에도 나오지만 서로 다른 사람입니다.","라멕은 아다와 씰라 두 아내를 맞아 일부다처가 처음 등장하고(4:19), 그 자녀들은 장막과 가축(야발), 수금과 퉁소(유발), 구리와 쇠 연장(두발가인)의 조상이 됩니다(4:20–22). 목축, 음악, 금속 기술이라는 문명의 출발이 가인의 계보에서 나타나는 것입니다.","마지막으로 라멕의 노래가 나옵니다. 라멕은 자신이 상처 입은 일로 사람을 죽였다고 자랑하며 “가인을 위하여는 벌이 칠 배일진대 라멕을 위하여는 칠십칠 배이리로다”라고 노래합니다(4:23–24). 가인에게 주어진 보호의 표가 보복을 과장하는 말로 변하여, 폭력이 한 세대 만에 크게 불어난 모습입니다."],"read":[{"ref":"창 4:15","hash":"gen-4:15","why":"가인에게 주신 표와 라멕의 노래를 견주어 보십시오."},{"ref":"마 18:21","hash":"mat-18:21","why":"“일곱 번을 일흔 번씩”이라는 용서의 가르침이 라멕의 칠십칠 배 보복과 대조된다고 보는 이들이 많습니다."},{"ref":"창 5:18","hash":"gen-5:18","why":"셋의 계보에 나오는 다른 에녹."}]},"era.primitive.cain-seth.3":{"flow":["아벨이 죽고 가인이 쫓겨난 뒤 아담과 하와는 다시 아들을 낳아 ‘셋’이라 이름 짓습니다. 하와는 하나님이 아벨 대신 다른 씨를 주셨다고 고백합니다(4:25). 아벨의 자리를 채우는 아들이라는 뜻입니다.","셋도 아들 에노스를 낳고, 본문은 짧게 덧붙입니다. “그 때에 사람이 비로소 여호와의 이름을 불렀더라”(4:26). 가인 계보가 성과 기술과 보복으로 기록된 것과 달리, 셋의 계보는 하나님을 부르는 것으로 소개됩니다. 이 두 계보는 이후 창세기에서 대비를 이루며 노아로 이어집니다."],"read":[{"ref":"창 5:3","hash":"gen-5:3","why":"아담이 셋을 낳은 기록."},{"ref":"눅 3:38","hash":"luk-3:38","why":"예수의 족보는 셋과 아담을 거쳐 “하나님께로” 이어집니다."},{"ref":"롬 10:13","hash":"rom-10:13","why":"“누구든지 주의 이름을 부르는 자는 구원을 얻으리라”."}]},"era.primitive.cain-seth.4":{"flow":["셋의 계보에 나오는 에녹은 65세에 므두셀라를 낳은 뒤 삼백 년 동안 하나님과 동행하며 자녀를 낳았고, 모두 365세를 살았습니다(5:21–23). 5장은 “~를 낳고 … 죽었더라”가 되풀이되는 족보인데, 에녹에게만 그 문구가 없습니다.","5:24은 “에녹이 하나님과 동행하더니 하나님이 그를 데려가시므로 세상에 있지 아니하였더라”고 합니다. 히브리서 11:5는 이를 믿음으로 해석하여, 에녹이 죽음을 보지 않고 옮겨졌다고 말합니다. 구약에서 비슷하게 죽음을 거치지 않고 하늘로 올려진 인물로는 엘리야가 있습니다(왕하 2:11).","유다서 14–15절은 “아담의 칠 대 손 에녹”의 예언을 인용합니다. 이 인용은 외경 「에녹1서」와의 관계 때문에 오래 논의되어 왔습니다."],"read":[{"ref":"히 11:5","hash":"heb-11:5","why":"에녹이 믿음으로 옮겨짐."},{"ref":"유 14","hash":null,"why":"에녹의 예언 인용."},{"ref":"왕하 2:11","hash":"2ki-2:11","why":"엘리야가 회오리바람을 타고 올라감."},{"ref":"시 49:15","hash":"psa-49:15","why":"하나님이 내 영혼을 거두신다는 소망의 노래."}]},"era.primitive.cain-seth.5":{"flow":["5장은 “이것이 아담 자손의 계보라”로 시작하며, 하나님의 형상으로 지어진 사람이 대를 이어 가는 모습을 한 줄로 보여 줍니다. 아담, 셋, 에노스, 게난, 마할랄렐, 야렛, 에녹, 므두셀라, 라멕, 노아로 이어지는 열 세대입니다(5:1–32).","각 사람에 대해 “몇 세에 누구를 낳고 몇 년을 더 살며 자녀를 낳았고 … 모두 몇 세를 살고 죽었더라”는 틀이 반복됩니다. 가장 오래 산 므두셀라는 969세입니다. 이 숫자를 문자 그대로 읽을지 상징으로 볼지는 학자들 사이에서 의견이 나뉘며, 본문은 숫자 자체보다 ‘죽음이 모든 사람에게 이어졌다’는 사실을 강조합니다(에녹은 예외).","라멕은 아들 노아의 이름을 지으며, 여호와께서 땅을 저주하셔서 수고하는 우리를 이 아들이 위로할 것이라고 말합니다(5:29). 노아(‘노아흐’)는 ‘위로하다’(‘나함’)와 소리가 비슷합니다. 노아는 500세 후에 셈, 함, 야벳을 낳습니다(5:32)."],"read":[{"ref":"눅 3:36","hash":"luk-3:36","why":"예수의 족보에 이어지는 이 계보."},{"ref":"대상 1:1","hash":"1ch-1:1","why":"역대기의 족보는 아담에서 시작합니다."},{"ref":"롬 5:14","hash":"rom-5:14","why":"아담에서 모세까지 죽음이 왕 노릇함."}]},"era.primitive.noah.1":{"flow":["본문은 먼저 상황을 이렇게 요약합니다. 사람의 죄악이 세상에 가득하고 마음의 생각과 계획이 항상 악할 뿐이어서(6:5), 하나님이 사람 지으심을 한탄하십니다(6:6). 땅은 포악으로 가득했습니다(6:11). 그러나 노아는 “여호와께 은혜를 입었더라”(6:8). 그는 의인이며 당대에 완전한 자로, 하나님과 동행했습니다(6:9).","하나님은 방주를 만들라고 지시하십니다. 고페르 나무로 길이 300규빗, 너비 50규빗, 높이 30규빗이며(6:15), 1규빗을 약 45cm로 보면 길이 약 135m, 너비 약 22m, 높이 약 13m 규모입니다. 3층으로 만들고 위에 창을 내며 옆에 문을 둡니다(6:16).","하나님은 노아와 언약을 세우시겠다고 말씀하시고(6:18) 아내와 세 아들과 며느리들, 그리고 각종 생물 암수를 방주로 들이라고 하십니다(6:19–21). 이 장은 “노아가 그와 같이 하여 하나님이 자기에게 명하신 대로 다 준행하였더라”(6:22)로 끝납니다."],"read":[{"ref":"벧후 2:5","hash":"2pe-2:5","why":"노아는 “의를 전파하는 자”."},{"ref":"히 11:7","hash":"heb-11:7","why":"노아가 믿음으로 방주를 준비함."},{"ref":"마 24:37","hash":"mat-24:37","why":"인자의 임함이 노아의 때와 같다는 말씀."},{"ref":"겔 14:14","hash":"ezk-14:14","why":"에스겔이 노아를 의인으로 언급."}]},"era.primitive.noah.2":{"flow":["하나님은 노아에게 “너와 네 온 집은 방주로 들어가라”고 하십니다(7:1). 개역한글 7:2–3은 정결한 짐승은 암수 일곱씩, 부정한 것은 암수 둘씩, 공중의 새도 암수 일곱씩을 데려오라고 합니다. 이는 방주에서 나온 뒤 드릴 제사(8:20)를 염두에 둔 구분으로 읽힙니다.","칠 일 뒤에 사십 주야 비가 내린다고 예고되고(7:4), 노아가 육백 세 되던 해 둘째 달 열이렛날 “큰 깊음의 샘들이 터지며 하늘의 창들이 열려” 홍수가 시작됩니다(7:11). 땅 아래 물과 하늘 위의 물이 함께 쏟아졌다는 표현입니다. 모든 생물이 짝을 지어 들어가자 여호와께서 문을 닫으셨다고 기록합니다(7:16). 방주의 문을 닫은 분이 노아가 아니라 하나님이라는 말입니다."],"read":[{"ref":"창 6:19","hash":"gen-6:19","why":"방주에 들일 생물의 지시."},{"ref":"마 24:38","hash":"mat-24:38","why":"홍수 전에도 사람들은 먹고 마시고 장가들었다."},{"ref":"눅 17:26","hash":"luk-17:26","why":"노아의 때와 인자의 날."}]},"era.primitive.noah.3":{"flow":["물이 땅에 넘쳐 방주가 물 위에 떠다닙니다(7:17–18). 물이 점점 불어 높은 산이 다 잠기고, 그 위로 15규빗(약 6.7m) 올라가 덮였다고 기록합니다(7:19–20). 땅 위에서 호흡이 있는 모든 것이 죽고 오직 노아와 방주 안에 있는 것만 남았으며(7:21–23), 물은 백오십 일 동안 땅에 넘쳤습니다(7:24).","8장에서 하나님이 노아를 “기억하시고” 바람을 일으켜 물이 줄어들고(8:1), 일곱째 달 열이렛날 방주가 “아라랏 산”에 머뭅니다(8:4). 히브리어 본문은 ‘아라랏 산들’(복수)이라 하며, 이 이름은 아시리아 자료의 ‘우라르투’(오늘날 튀르키예 동부 일대)와 연결되는 지역 이름으로 이해됩니다. 방주가 닿은 정확한 봉우리는 본문이 밝히지 않으며 위치는 확정되지 않았습니다."],"read":[{"ref":"창 8:1","hash":"gen-8:1","why":"하나님이 노아를 기억하심."},{"ref":"벧전 3:20","hash":"1pe-3:20","why":"노아 때 물로 구원받은 팔 명."},{"ref":"시 29:10","hash":"psa-29:10","why":"여호와께서 홍수 때에도 좌정하심."}]},"era.primitive.noah.4":{"flow":["물이 줄어들자 노아는 창을 열어 까마귀를 내보내고, 이어 비둘기를 세 번 내보냅니다. 두 번째에는 올리브 새 잎사귀를 물고 돌아와 물이 빠졌음을 알리고(8:11), 세 번째에는 돌아오지 않습니다(8:12). 홍수가 시작된 날부터 땅이 완전히 마른 날까지는 만 1년 10일(2월 17일→이듬해 2월 27일)이 걸렸습니다(7:11; 8:14).","하나님이 “너는 … 방주에서 나오라”고 하시자 노아와 가족과 모든 생물이 나옵니다(8:15–19). 노아가 처음 한 일은 제단을 쌓고 정결한 짐승으로 번제를 드리는 것이었습니다(8:20). 여호와께서 그 향기를 받으시고 “다시는 사람으로 말미암아 땅을 저주하지 아니하리니 … 땅이 있을 동안에는 심음과 거둠과 추위와 더위와 여름과 겨울과 낮과 밤이 쉬지 아니하리로다”(8:21–22)고 마음에 정하십니다."],"read":[{"ref":"창 8:21","hash":"gen-8:21","why":"사람의 마음의 계획이 악하여도 땅을 다시 저주하지 않으시겠다는 약속."},{"ref":"사 54:9","hash":"isa-54:9","why":"노아의 홍수를 두고 맹세하신 하나님."},{"ref":"벧전 3:21","hash":"1pe-3:21","why":"홍수를 세례와 견주는 베드로의 설명."}]},"era.primitive.noah.5":{"flow":["하나님은 노아와 아들들에게 복을 주시며 “생육하고 번성하여 땅에 충만하라”고 하십니다(9:1). 이제 사람에게 모든 동물을 먹을 것으로 허락하시되 “피째 먹지 말라”고 하고(9:3–4), 사람의 피를 흘린 자는 그 피를 흘리게 되리라고 선언합니다. 그 이유는 “하나님이 자기 형상대로 사람을 지으셨음”입니다(9:6).","이어 하나님은 노아와 그 후손, 땅의 모든 생물과 언약을 세우십니다. 다시는 홍수로 모든 육체를 멸하지 않겠다는 약속입니다(9:9–11). 그 언약의 표는 “구름 속의 무지개”입니다(9:13–16). 히브리어 ‘케셰트’는 ‘활’이라는 낱말과 같아, 전쟁의 활이 하늘에 걸렸다는 이미지로 읽는 이들도 있습니다. 하나님이 무지개를 보시고 이 “영원한 언약”을 기억하십니다(9:16)."],"read":[{"ref":"사 54:9","hash":"isa-54:9","why":"노아의 홍수 같은 물을 다시 땅에 덮이지 않게 하신다는 맹세."},{"ref":"겔 1:28","hash":"ezk-1:28","why":"비 오는 날 구름 속의 무지개 같은 광채."},{"ref":"계 4:3","hash":"rev-4:3","why":"보좌를 둘러싼 무지개."},{"ref":"벧후 3:5","hash":"2pe-3:5","why":"물로 멸망한 옛 세상과 불로 심판받을 지금의 세상."}]},"era.primitive.nations.1":{"flow":["10장은 홍수 뒤 노아의 세 아들 셈, 함, 야벳의 자손을 “족보”로 기록한 이른바 ‘민족 목록’입니다. 야벳의 아들은 고멜, 마곡, 마대, 야완, 두발, 메섹, 디라스이며(10:2), 야완의 자손은 엘리사, 달시스, 깃딤, 도다님입니다(10:4). 이들이 “섬들의 백성”으로 나뉘어 각기 언어와 종족과 나라대로 살았다고 합니다(10:5).","여기 나오는 이름은 한 사람의 이름이면서 민족이나 지역의 이름으로 쓰입니다. 예를 들어 야완은 이오니아(그리스 계통), 두발과 메섹은 소아시아 동부 일대, 깃딤은 구브로(키프로스)와 연결해 보는 견해가 많습니다. 이 지도 위의 점들은 OpenBible이 그 이름을 비정한 지점일 뿐 해당 민족이 정확히 그곳에 살았다는 뜻은 아닙니다.","창세기 10장에는 야벳 14, 함 30, 셈 26개의 이름이 나오며 이를 합쳐 전통적으로 ‘70 민족’이라고 부릅니다. 이는 당시 알려진 세계 전체를 그려 보인 것으로 이해됩니다."],"read":[{"ref":"창 10:32","hash":"gen-10:32","why":"노아의 자손이 나뉘어 민족들이 되었다는 결론."},{"ref":"대상 1:5","hash":"1ch-1:5","why":"역대기의 같은 계보."},{"ref":"행 17:26","hash":"act-17:26","why":"한 혈통으로 모든 민족을 만드셨다는 바울의 설교."}]},"era.primitive.nations.2":{"flow":["함의 아들은 구스, 미스라임(이집트), 붓, 가나안입니다(10:6). 구스의 자손 가운데 니므롯은 “세상에 처음 영걸”이며 “여호와 앞에서 용감한 사냥꾼”이라 불립니다(10:8–9). 그의 나라는 시날 땅의 바벨, 에렉, 악갓, 갈레에서 시작되었고(10:10), 이어 앗수르 쪽으로 나아가 니느웨, 갈라 등을 세웠다고 전합니다(10:11–12). 이 문장은 “앗수르가 나아가”로도 번역할 수 있어 번역본마다 다릅니다.","미스라임의 자손에는 블레셋이 나온 가슬루힘과 갑돌이 있고(10:13–14), 가나안의 자손은 시돈, 헷, 여부스, 아모리, 기르가스, 히위 등 훗날 가나안 땅의 족속들입니다(10:15–18). 가나안의 경계는 시돈에서 그랄을 지나 가사까지, 소돔·고모라·아드마·스보임을 지나 라사까지로 그려집니다(10:19).","본문은 구스(남쪽, 오늘날 수단 일대)부터 시날(메소포타미아 남부), 가나안까지 널리 퍼진 세계를 보여 줍니다. 이런 이름들은 이후 성경 이야기에서 이스라엘의 이웃이나 대적으로 다시 등장합니다."],"read":[{"ref":"미 5:6","hash":"mic-5:6","why":"“앗수르 땅과 니므롯의 땅”."},{"ref":"대상 1:8","hash":"1ch-1:8","why":"역대기의 함 계보."},{"ref":"암 9:7","hash":"amo-9:7","why":"갑돌에서 블레셋을 인도하신 하나님."}]},"era.primitive.nations.3":{"flow":["셈은 “에벨 온 자손의 조상”이며 야벳의 형으로 소개됩니다(10:21). 아들은 엘람, 앗수르, 아르박삿, 룻, 아람입니다(10:22). 이 목록에는 오늘날의 이란(엘람), 이라크 북부(앗수르), 소아시아(룻), 시리아(아람) 일대와 연결되는 이름이 담깁니다.","아르박삿에서 셀라, 에벨로 이어지고, 에벨에게는 두 아들이 있습니다. 하나는 “그때에 땅이 나뉘었음이라”는 설명이 붙은 ‘벨렉’(‘나뉨’)이고, 다른 하나는 욕단입니다(10:25). 욕단의 아들 열세 명의 이름과 거처가 이어집니다(10:26–30). 히브리 사람의 이름도 ‘에벨’에서 왔다고 보는 견해가 있습니다.","10장은 “이들은 셈의 자손이니 …”(10:31)라는 말로 끝나, 홍수 후 세계가 나뉜 모습을 한 번 더 확인합니다. 곧바로 11장에서 이 나뉨의 한 장면이 바벨 이야기로 자세히 소개됩니다."],"read":[{"ref":"창 11:10","hash":"gen-11:10","why":"셈에서 아브람으로 좁혀지는 계보."},{"ref":"눅 3:34","hash":"luk-3:34","why":"예수의 족보에도 이어집니다."},{"ref":"대상 1:17","hash":"1ch-1:17","why":"역대기의 셈 계보."}]},"era.primitive.nations.4":{"flow":["온 땅의 구음과 언어가 하나였던 사람들이 동쪽으로 옮겨 가다가 시날 평지에 이르러 정착합니다(11:1–2). 그들은 “벽돌을 만들어 견고히 굽고” 돌 대신 벽돌을, 석회 대신 역청을 사용합니다(11:3). 메소포타미아의 평지에는 돌이 드물고 흙벽돌 건축이 흔했습니다.","그들의 계획은 “성읍과 탑을 쌓아 그 꼭대기를 하늘에 닿게 하여 우리 이름을 내고 온 지면에 흩어짐을 면하자”는 것이었습니다(11:4). 이는 창세기 1:28과 9:1의 “땅에 충만하라”는 말씀과 대조됩니다. 하나님은 내려와 보시고 그들의 언어를 혼잡하게 하여 서로 알아듣지 못하게 하시고, 사람들은 온 지면으로 흩어집니다(11:5–8).","그 성읍의 이름이 ‘바벨’이 된 것은 “여호와께서 거기서 온 땅의 언어를 혼잡하게 하셨음”이라 합니다(11:9). 히브리어 ‘발랄’(혼잡하게 하다)과 말소리가 닮았습니다. 아카드어로 ‘바빌루’는 ‘신의 문’이라는 뜻이어서, 본문은 같은 이름을 다른 뜻으로 읽는 말놀이를 담고 있습니다. 시날의 계단식 신전탑(지구라트)과 이 이야기를 관련짓는 견해가 많습니다."],"read":[{"ref":"행 2:6","hash":"act-2:6","why":"오순절에 각 사람이 자기 언어로 듣게 됨."},{"ref":"창 10:5","hash":"gen-10:5","why":"민족들이 언어대로 나뉨."},{"ref":"습 3:9","hash":"zep-3:9","why":"입술을 깨끗하게 하여 다 여호와의 이름을 부르게 하실 것."}]},"era.primitive.nations.5":{"flow":["바벨 이야기 뒤에 이어지는 계보로, 홍수 후 이 년 되던 때 셈(100세)이 아르박삿을 낳고(11:10), 셀라, 에벨, 벨렉, 르우, 스룩, 나홀을 거쳐 데라에 이릅니다(11:11–25). 데라는 70세에 아브람, 나홀, 하란을 낳습니다(11:26).","10장과 대비해서 읽으면 의미가 보입니다. 10장은 노아의 자손이 온 세계로 넓게 나뉜 모습(수평)이었고, 11:10–26은 한 줄의 가계가 아브람에게로 좁혀져 가는 모습(수직)입니다. 이후 12장에서 하나님이 아브람을 부르시고 “땅의 모든 족속이 너로 말미암아 복을 얻을 것”이라 약속하신 이야기는 ‘흩어진 민족들’에게 향한 하나님의 응답으로 읽을 수 있습니다."],"read":[{"ref":"창 12:1","hash":"gen-12:1","why":"아브람을 부르심."},{"ref":"눅 3:34","hash":"luk-3:34","why":"예수의 족보에도 이어지는 이름들."},{"ref":"수 24:2","hash":"jos-24:2","why":"데라가 강 저편에서 다른 신들을 섬겼음."}]}};
